INSERT INTO products (id, name, slug, description, short_description, category_id, subcategory_id, brand_id, base_sku, barcode, cost_price, selling_price, promo_price, weight_kg, height_cm, width_cm, length_cm, status, is_new, is_featured, is_best_seller, gender) VALUES ('prod-nike-air-max-90', 'Tênis Nike Air Max 90 Infrared Classic', 'nike-air-max-90-infrared', 'Nada mais marcante, nada mais comprovado. O Nike Air Max 90 permanece fiel às suas raízes originais com a icônica sola Waffle, sobreposições costuradas e os toques clássicos de TPU que adicionam um estilo sem esforço. Amortecimento Max Air visível desenvolvido originalmente para corrida de alta performance.', 'Ícone dos anos 90 com amortecimento Max Air visível e cabedal em couro e mesh respirável.', 'cat-tenis', 'sub-tenis-casual', 'b-nike', 'NK-AM90-INF', '7891002003011', 420, 799.9, 699.9, 0.95, 14, 22, 34, 'active', TRUE, TRUE, TRUE, 'unissex');
