INSERT INTO products (id, name, slug, description, short_description, category_id, subcategory_id, brand_id, base_sku, barcode, cost_price, selling_price, promo_price, weight_kg, height_cm, width_cm, length_cm, status, is_new, is_featured, is_best_seller, gender) VALUES ('prod-mizuno-prophecy', 'Tênis Mizuno Wave Prophecy 12 Platinum', 'mizuno-wave-prophecy-12-platinum', 'O ápice da tecnologia Mizuno. A icônica placa Wave infinita proporciona absorção de impacto incomparável, estabilidade biomecânica e um visual imponente que dominou as ruas brasileiras.', 'Amortecimento Wave supremo com placa articulada, acabamento premium espelhado.', 'cat-tenis', 'sub-tenis-corrida', 'b-mizuno', 'MZ-PROP-12PLT', NULL, 750, 1399.9, 1249.9, 1.1, 15, 23, 35, 'active', TRUE, TRUE, TRUE, 'masculino');
